TreeSet<Integer> set = new TreeSet<>(List.of(80, 23, 10, 90, 50));

System.out.println(set.lower(50) + " " + set.floor(55) + " "
        + set.higher(90) + " " + set.ceiling(80));

Map<Integer, String> map = new TreeMap<>();
map.put(101, "Aditya");
map.put(102, "Rohit");
map.put(103, "Rohan");

System.out.println(map.putIfAbsent(103, "Abhay"));
map.remove(101, "Abhay");
map.replace(102, "Aditya", "Sonu");
map.replace(101, "Sonu");
System.out.println(map + " " + map.getOrDefault(105, "Unknown"));
